<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Facades\File;
class DatabaseBackupService {
 private const MEDIA_DIRECTORIES=['asset/front-end/img/Product_image','asset/front-end/img/banners','asset/front-end/img/branding','asset/front-end/img/payments','asset/front-end/img/payment-proofs','asset/front-end/img/feature-cards','asset/front-end/img/featured-brands'];
 public function create($createdBy='scheduler'){$filename='ecommerce-'.date('Y-m-d-His').'.sql.gz';$id=DB::table('system_backups')->insertGetId(['filename'=>$filename,'disk'=>'local','status'=>'creating','created_by'=>$createdBy,'created_at'=>now(),'updated_at'=>now()]);$relative='backups/'.$filename;$absolute=storage_path('app/'.$relative);if(!is_dir(dirname($absolute)))mkdir(dirname($absolute),0755,true);try{$out=gzopen($absolute,'wb9');if(!$out)throw new \RuntimeException('Unable to create backup file.');gzwrite($out,"-- Ecommerce database backup\n-- Created: ".date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n\n");$tables=DB::select('SHOW TABLES');foreach($tables as $row){$values=array_values((array)$row);$table=$values[0];$create=DB::select("SHOW CREATE TABLE `".str_replace('`','``',$table)."`");$definition=array_values((array)$create[0])[1];gzwrite($out,"DROP TABLE IF EXISTS `{$table}`;\n{$definition};\n");DB::table($table)->orderBy(DB::raw('1'))->chunk(250,function($rows)use($out,$table){foreach($rows as $row){$columns=array_keys((array)$row);$values=array_map(function($value){return is_null($value)?'NULL':DB::connection()->getPdo()->quote((string)$value);},array_values((array)$row));gzwrite($out,"INSERT INTO `{$table}` (`".implode('`,`',$columns)."`) VALUES (".implode(',',$values).");\n");}});gzwrite($out,"\n");}gzwrite($out,"SET FOREIGN_KEY_CHECKS=1;\n");gzclose($out);$size=filesize($absolute);DB::table('system_backups')->where('id',$id)->update(['status'=>'completed','size_bytes'=>$size,'updated_at'=>now()]);$this->prune(14);return $id;}catch(\Throwable $e){if(isset($out)&&is_resource($out))gzclose($out);if(file_exists($absolute))@unlink($absolute);DB::table('system_backups')->where('id',$id)->update(['status'=>'failed','error'=>substr($e->getMessage(),0,2000),'updated_at'=>now()]);throw $e;}}
 public function restore(string $path): void {$handle=@gzopen($path,'rb');if(!$handle)throw new \RuntimeException('Unable to read the compressed backup file.');$statement='';$single=false;$double=false;$backtick=false;$escaped=false;$pendingPrefix=null;$pendingValues=[];$flushInserts=function()use(&$pendingPrefix,&$pendingValues){if($pendingPrefix!==null&&!empty($pendingValues))DB::unprepared($pendingPrefix.implode(',', $pendingValues).';');$pendingPrefix=null;$pendingValues=[];};$execute=function($sql)use(&$flushInserts,&$pendingPrefix,&$pendingValues){$sql=trim($sql);if($sql===''||preg_match('/^(--|#)/',$sql))return;$sql=rtrim($sql,';');$valuesPos=stripos($sql,'VALUES');if(stripos($sql,'INSERT INTO')===0&&$valuesPos!==false){$prefix=substr($sql,0,$valuesPos).'VALUES ';$values=trim(substr($sql,$valuesPos+6));if($pendingPrefix!==$prefix)$flushInserts();$pendingPrefix=$prefix;$pendingValues[]=$values;return;}$flushInserts();DB::unprepared($sql.';');};try{DB::unprepared('SET FOREIGN_KEY_CHECKS=0');while(!gzeof($handle)){$chunk=gzread($handle,8192);$length=strlen($chunk);for($i=0;$i<$length;$i++){$char=$chunk[$i];$statement.=$char;if($escaped){$escaped=false;continue;}if(($single||$double)&&$char==='\\'){$escaped=true;continue;}if(!$double&&!$backtick&&$char==="'"){$single=!$single;continue;}if(!$single&&!$backtick&&$char==='"'){$double=!$double;continue;}if(!$single&&!$double&&$char==='`'){$backtick=!$backtick;continue;}if($char===';'&&!$single&&!$double&&!$backtick){$execute($statement);$statement='';}}}$execute($statement);$flushInserts();DB::unprepared('SET FOREIGN_KEY_CHECKS=1');}catch(\Throwable $e){try{DB::unprepared('SET FOREIGN_KEY_CHECKS=1');}catch(\Throwable $ignored){}throw $e;}finally{gzclose($handle);}}
 public function createMedia($createdBy='scheduler'){ $filename='ecommerce-'.date('Y-m-d-His').'.media.tar.gz';$id=DB::table('system_backups')->insertGetId(['filename'=>$filename,'disk'=>'local','status'=>'creating','created_by'=>$createdBy,'created_at'=>now(),'updated_at'=>now()]);$tarPath=storage_path('app/backups/'.substr($filename,0,-3));$archivePath=$tarPath.'.gz';try{$archive=new \PharData($tarPath);$this->addMediaFiles($archive);$archive->compress(\Phar::GZ);unset($archive);if(is_file($tarPath))@unlink($tarPath);$size=filesize($archivePath);DB::table('system_backups')->where('id',$id)->update(['status'=>'completed','size_bytes'=>$size,'updated_at'=>now()]);$this->prune(14);return $id;}catch(\Throwable $e){if(is_file($tarPath))@unlink($tarPath);if(is_file($archivePath))@unlink($archivePath);DB::table('system_backups')->where('id',$id)->update(['status'=>'failed','error'=>substr($e->getMessage(),0,2000),'updated_at'=>now()]);throw $e;}}
 public function restoreMedia(string $path): void {$temp=storage_path('app/media-restore-'.str_random(24));$tarPath=preg_replace('/\.gz$/','',$path);try{$archive=new \PharData($path);if(!is_file($tarPath))$archive->decompress();$archive=new \PharData($tarPath);$this->validateArchiveEntries($archive,'media');$archive->extractTo($temp,null,true);$mediaRoot=$temp.'/media';if(is_dir($mediaRoot)){$files=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($mediaRoot,\FilesystemIterator::SKIP_DOTS));foreach($files as $file){if(!$file->isFile())continue;$relative=str_replace('\\','/',substr($file->getPathname(),strlen($mediaRoot)+1));if(strpos($relative,'..')!==false)throw new \RuntimeException('The media backup contains an unsafe file path.');$destination=public_path($relative);if(!is_dir(dirname($destination)))mkdir(dirname($destination),0755,true);if(!copy($file->getPathname(),$destination))throw new \RuntimeException('Unable to restore media file: '.$relative);}}}finally{if(is_file($tarPath))@unlink($tarPath);if(is_dir($temp))File::deleteDirectory($temp);}}
 private function addMediaFiles($archive): void {foreach(self::MEDIA_DIRECTORIES as $directory){$root=public_path($directory);if(!is_dir($root))continue;$files=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS));foreach($files as $file){if($file->isFile()){$relative=str_replace('\\','/',substr($file->getPathname(),strlen(public_path())+1));$archive->addFile($file->getPathname(),'media/'.$relative);}}}}
 public function createFull($createdBy='scheduler'){ $id=$this->create($createdBy);$backup=DB::table('system_backups')->where('id',$id)->first();$sqlPath=storage_path('app/backups/'.$backup->filename);$archiveName=preg_replace('/\.sql\.gz$/','.full.tar.gz',$backup->filename);$tarPath=storage_path('app/backups/'.substr($archiveName,0,-3));$archivePath=$tarPath.'.gz';try{$archive=new \PharData($tarPath);$archive->addFile($sqlPath,'database.sql.gz');$this->addMediaFiles($archive);$archive->compress(\Phar::GZ);unset($archive);if(is_file($tarPath))@unlink($tarPath);if(is_file($sqlPath))@unlink($sqlPath);$size=filesize($archivePath);DB::table('system_backups')->where('id',$id)->update(['filename'=>$archiveName,'size_bytes'=>$size,'updated_at'=>now()]);return $id;}catch(\Throwable $e){if(is_file($tarPath))@unlink($tarPath);if(is_file($archivePath))@unlink($archivePath);DB::table('system_backups')->where('id',$id)->update(['status'=>'failed','error'=>substr($e->getMessage(),0,2000),'updated_at'=>now()]);throw $e;}}
 public function restoreFull(string $path): void {$temp=storage_path('app/restore-'.str_random(24));$tarPath=preg_replace('/\.gz$/','',$path);try{$archive=new \PharData($path);if(!is_file($tarPath))$archive->decompress();$archive=new \PharData($tarPath);$this->validateArchiveEntries($archive,'full');$archive->extractTo($temp,null,true);$this->restore($temp.'/database.sql.gz');$mediaRoot=$temp.'/media';if(is_dir($mediaRoot)){$files=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($mediaRoot, \FilesystemIterator::SKIP_DOTS));foreach($files as $file){if(!$file->isFile())continue;$relative=str_replace('\\','/',substr($file->getPathname(),strlen($mediaRoot)+1));if(strpos($relative,'..')!==false)throw new \RuntimeException('The full backup contains an unsafe media path.');$destination=public_path($relative);if(!is_dir(dirname($destination)))mkdir(dirname($destination),0755,true);if(!copy($file->getPathname(),$destination))throw new \RuntimeException('Unable to restore media file: '.$relative);}}}finally{if(is_file($tarPath))@unlink($tarPath);if(is_dir($temp))File::deleteDirectory($temp);}}
 private function validateArchiveEntries($archive,string $type): void {$iterator=new \RecursiveIteratorIterator($archive, \RecursiveIteratorIterator::SELF_FIRST);foreach($iterator as $entry=>$file){$entry=$this->archiveRelativePath((string)$entry);if($entry===''||$entry==='.'||$entry==='media')continue;if(strpos($entry,'..')!==false||strpos($entry,'/')===0||preg_match('#^[A-Za-z]:/#',$entry))throw new \RuntimeException('The '.($type==='media'?'media':'full').' backup contains an unsafe file path.');if($type==='media'&&strpos($entry,'media/')!==0)throw new \RuntimeException('The media backup contains an unsafe file path.');if($type==='full'&&$entry!=='database.sql.gz'&&strpos($entry,'media/')!==0)throw new \RuntimeException('The full backup contains an unsupported file path.');}}
 private function archiveRelativePath(string $entry): string {$entry=str_replace('\\','/',trim($entry));if(strpos($entry,'phar://')===0){$mediaPos=strpos($entry,'/media');$databasePos=strpos($entry,'/database.sql.gz');if($mediaPos!==false&&($databasePos===false||$mediaPos<$databasePos))$entry=substr($entry,$mediaPos+1);elseif($databasePos!==false)$entry=substr($entry,$databasePos+1);}return ltrim($entry,'/');}
 public function prune($days){$old=DB::table('system_backups')->where('created_at','<',now()->subDays($days))->get();foreach($old as $backup){Storage::disk($backup->disk)->delete('backups/'.$backup->filename);DB::table('system_backups')->where('id',$backup->id)->delete();}}
}
